import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

def route(url_path):
    def decorator(func):
        app.add_url_rule(url_path, func.__name__, func, methods=['GET'])
        return func
    return decorator

@route('/ping')
def ping():
    try:
        url = request.args.get('url')
        if not url:
            return jsonify({'error': 'URL parameter is required'}), 400

        # Запускаем команду ping
        result = subprocess.run(['ping', '-c', '4', url], capture_output=True, text=True, timeout=10)

        if result.returncode == 0:
            return jsonify({'output': result.stdout})
        else:
            return jsonify({'error': result.stderr}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Ping request timed out'}), 500
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)

