import subprocess
from functools import wraps

def route(url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # URL'yi sakla
            url_var = url
            # Ping komutunu çalıştır
            try:
                result = subprocess.run(['ping', '-c', '4', url_var], capture_output=True, text=True, check=True)
                output = result.stdout
            except subprocess.CalledProcessError as e:
                output = e.stderr
            # Sonucu döndür
            return func(output, url_var)
        return wrapper
    return decorator

@route("example.com")
def ping(output, url):
    return f"Ping to {url} completed. Output: {output}"
